function toWebSafeBase64(value: string) {
  return value.startsWith('ey') ? value : btoa(value).replace(/\+/g, '-').replace(/\//g, '_');
}

function createSupabaseFetch(supabaseKey: string) {
  return (input: RequestInfo | URL, init?: RequestInit) => {
    const headers = new Headers(init?.headers as HeadersInit | undefined);
    if (!headers.has('apikey')) {
      headers.set('apikey', supabaseKey);
    }
    if (input instanceof Request && headers.has('Authorization') === false) {
      const auth = input.headers.get('Authorization');
      if (auth) headers.set('Authorization', auth);
    }
    return fetch(input, { ...init, headers });
  };
}

function createSupabaseClient() {
  // قراءة المتغيرات بشكل آمن - لا نرمي خطأ يوقف الموقع
  const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL || '';
  const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY || '';

  if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
    console.warn('Supabase env vars missing - running in limited mode');
    // نرجع عميل وهمي عشان لا ينهار الموقع
    return { auth: {}, from: () => ({ select: () => Promise.resolve({ data: [], error: null }) }) } as any;
  }

  return createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
    auth: {
      storage: browserPreviewStorage,
      persistSession: true,
      autoRefreshToken: true,
    },
    global: {
      fetch: createSupabaseFetch(SUPABASE_PUBLISHABLE_KEY),
    }
  });
}

